var LANG_NEW_RAW3={"biryani":{"ja":["チキンビリヤニ","カラチ風ビリヤニ。スパイスのきいたチキン、香り高いバスマティ、家中に広がるダムの香り。","サフランライスと新鮮なコリアンダーのチキンビリヤニの皿"],"de":["Hähnchen-Biryani","Biryani nach Karachi-Art, gewürztes Hähnchen, duftender Basmati und das Dum-Aroma, das das ganze Haus erfüllt.","Ein Teller Hähnchen-Biryani mit Safranreis und frischem Koriander"],"tr":["Tavuk Biryani","Karaçi usulü biryani, baharatlı tavuk, kokulu basmati ve bütün evi dolduran dem kokusu.","Safranlı pilav ve taze kişnişli bir tabak tavuk biryani"],"bn":["চিকেন বিরিয়ানি","করাচি স্টাইলের বিরিয়ানি, মশলাদার মুরগি, সুগন্ধি বাসমতি এবং দমের গন্ধ যা পুরো বাড়ি ভরে দেয়।","জাফরান ভাত ও তাজা ধনেপাতা সহ এক প্লেট চিকেন বিরিয়ানি"]},"nihari":{"ja":["ビーフニハリ","ゆっくり煮込んだニハリ。柔らかい肉、深いマサラ、ナンで食べ切るグレービー。","深いマサラとショウガのビーフニハリのボウル"],"de":["Rindfleisch-Nihari","Langsam gekochtes Nihari, zartes Fleisch, tiefes Masala und die Soße, die mit Naan zu Ende geht.","Eine Schale Rindfleisch-Nihari mit tiefem Masala und Ingwer"],"tr":["Dana Nihari","Yavaş pişmiş nihari, yumuşak et, derin masala ve naan ile biten sos.","Derin masala ve zencefilli bir kâse dana nihari"],"bn":["বিফ নিহারি","ধীরে রান্না করা নিহারি, নরম মাংস, গভীর মশলা এবং নানের সঙ্গে শেষ হওয়া ঝোল।","গভীর মশলা ও আদা সহ এক বাটি বিফ নিহারি"]},"karahi":{"ja":["チキンカラヒ","ダバ風カラヒ。新鮮なトマト、ショウガ、青唐辛子。まさにカラヒのダバの味。","トマトと青唐辛子の入ったカダイのチキンカラヒ"],"de":["Hähnchen-Karahi","Karahi nach Dhaba-Art, frische Tomaten, Ingwer und grüne Chilis, genau der Geschmack eines Karahi-Dhaba.","Hähnchen-Karahi in einer Kadhai mit Tomaten und grünen Chilis"],"tr":["Tavuk Karahi","Dhaba usulü karahi, taze domates, zencefil ve yeşil biber, tam bir karahi dhabasının tadı.","Domates ve yeşil biberli kadhai tavasında tavuk karahi"],"bn":["চিকেন কড়াহি","ঢাবা স্টাইলের কড়াহি, তাজা টমেটো, আদা ও কাঁচা লঙ্কা, ঠিক কড়াহি ঢাবার স্বাদ।","টমেটো ও কাঁচা লঙ্কা সহ কড়াইয়ে চিকেন কড়াহি"]},"daal":{"ja":["ダールフライ（タルカダール）","家庭風ダール。クミンと赤唐辛子のタルカをのせ、ご飯やロティにぴったり。","赤唐辛子とクミンのタルカをかけたダールのボウル"],"de":["Daal Fry (Tadka Daal)","Hausgemachte Daal mit einem Tadka aus Kreuzkümmel und rotem Chili obendrauf, perfekt zu Reis oder Roti.","Eine Schale Tadka Daal mit rotem Chili und Kreuzkümmel"],"tr":["Daal Fry (Tadka Daal)","Üzerinde kimyon ve kırmızı biber tadkası olan ev usulü daal, pilav veya roti ile mükemmel.","Kırmızı biber ve kimyon tadkalı bir kâse tadka daal"],"bn":["ডাল ফ্রাই (তড়কা ডাল)","ঘরোয়া ডাল, উপরে জিরা ও লাল লঙ্কার তড়কা, ভাত বা রুটির সঙ্গে দারুণ।","লাল লঙ্কা ও জিরার তড়কা সহ এক বাটি তড়কা ডাল"]},"chapli":{"ja":["チャプリケバブ","ペシャワール風チャプリケバブ。ザクロの種、トマト、一口ごとに感じるマサラ。","グリーンチャツネとサラダのチャプリケバブの皿"],"de":["Chapli Kebab","Chapli Kebab aus Peshawar, Granatapfelkerne, Tomate und das Masala, das man bei jedem Bissen spürt.","Ein Teller Chapli Kebabs mit grünem Chutney und Salat"],"tr":["Chapli Kebap","Peşaver chapli kebabı, nar taneleri, domates ve her lokmada hissedilen masala.","Yeşil chutney ve salatalı bir tabak chapli kebap"],"bn":["চাপলি কাবাব","পেশোয়ারি চাপলি কাবাব, ডালিমের বীজ, টমেটো এবং প্রতিটি কামড়ে অনুভূত মশলা।","সবুজ চাটনি ও সালাদ সহ এক প্লেট চাপলি কাবাব"]},"tikka":{"ja":["チキンティッカ","タンドール風チキンティッカ。ヨーグルトとスパイスに漬け、レモンとチャートマサラで仕上げ。","スパイスと炭の香りのチキンティッカ"],"de":["Hähnchen-Tikka","Hähnchen-Tikka nach Tandoori-Art, in Joghurt und Gewürzen mariniert, mit Zitrone und Chaat Masala verfeinert.","Hähnchen-Tikka-Stücke mit Gewürzen und Grillaroma"],"tr":["Tavuk Tikka","Tandır usulü tavuk tikka, yoğurt ve baharatlarla marine edilmiş, limon ve chaat masala ile tamamlanmış.","Baharat ve köz kokulu tavuk tikka parçaları"],"bn":["চিকেন টিক্কা","তন্দুরি স্টাইলের চিকেন টিক্কা, দই ও মশলায় ম্যারিনেট করা, লেবু ও চাট মশলা দিয়ে শেষ করা।","মশলা ও কয়লার গন্ধ সহ চিকেন টিক্কার টুকরো"]},"halwapuri":{"ja":["ハルワプリの朝食","日曜日の朝食。ふっくらしたプリ、柔らかいセモリナのハルワ、スパイスのきいたひよこ豆。ラホールそのもの。","ハルワプリの朝食。ふっくらしたプリ、ハルワ、ひよこ豆"],"de":["Halwa-Puri-Frühstück","Sonntagsfrühstück, aufgeblasene Puri, weicher Grieß-Halwa und gewürzte Kichererbsen, genau wie in Lahore.","Halwa-Puri-Frühstück, aufgeblasene Puri, Halwa und Kichererbsen"],"tr":["Halwa Puri Kahvaltısı","Pazar kahvaltısı, kabarmış puri, yumuşak irmik helvası ve baharatlı nohut, tıpkı Lahor gibi.","Halwa puri kahvaltısı, kabarmış puri, helva ve nohut"],"bn":["হালুয়া পুরি নাশতা","রবিবারের নাশতা, ফোলা পুরি, নরম সুজির হালুয়া ও মশলাদার ছোলা, ঠিক লাহোরের মতো।","হালুয়া পুরি নাশতা, ফোলা পুরি, হালুয়া ও ছোলা"]},"samosa":{"ja":["パンジャブ風サモサ","サクサクのパンジャブ風サモサ。スパイスのきいたジャガイモ、グリーンチャツネとお茶。最高の夕方の組み合わせ。","チャツネ付きのサモサの皿"],"de":["Punjabi-Samosa","Knusprige Punjabi-Samosa, gewürzte Kartoffel, grünes Chutney und Tee, das beste Paar am Abend.","Ein Teller Samosas mit Chutney"],"tr":["Pencap Samosa","Çıtır Pencap samosa, baharatlı patates, yeşil chutney ve çay, akşamın en iyi ikilisi.","Chutneyli bir tabak samosa"],"bn":["পাঞ্জাবি সমোসা","মচমচে পাঞ্জাবি সমোসা, মশলাদার আলু, সবুজ চাটনি ও চা, সন্ধ্যার সেরা জুটি।","চাটনি সহ এক প্লেট সমোসা"]},"bunkebab":{"ja":["バンケバブ","カラチの屋台風バンケバブ。シャミケバブ、タマリンドチャツネ、タマネギをバンに挟む。","バンの中のケバブ、タマネギ、チャツネのバンケバブ"],"de":["Bun Kebab","Bun Kebab nach Straßenart aus Karachi, Shami Kebab, Tamarinden-Chutney und Zwiebel, in einem Brötchen.","Bun Kebab, Kebab, Zwiebel und Chutney in einem Brötchen"],"tr":["Bun Kebap","Karaçi sokak usulü bun kebap, şami kebap, demirhindi chutney ve soğan, bir ekmek içinde.","Ekmek içinde kebap, soğan ve chutneyli bun kebap"],"bn":["বান কাবাব","করাচি স্ট্রিট স্টাইলের বান কাবাব, শামি কাবাব, তেঁতুলের চাটনি ও পেঁয়াজ, বানের ভিতরে।","বানের ভিতরে কাবাব, পেঁয়াজ ও চাটনি সহ বান কাবাব"]},"gulabjamun":{"ja":["グラブジャムン","柔らかいグラブジャムン。コヤ、シロップ、カルダモン。イードや祝宴でいちばん愛されるお菓子。","バラの香りのシロップに浸したグラブジャムン"],"de":["Gulab Jamun","Weicher Gulab Jamun, Khoya, Sirup und Kardamom, die beliebteste Süßigkeit für Eid und Feste.","Gulab Jamun in Sirup mit Rosenaroma"],"tr":["Gulab Jamun","Yumuşak gulab jamun, khoya, şerbet ve kakule, Bayram ve ziyafetlerin en sevilen tatlısı.","Gül kokulu şerbette gulab jamun"],"bn":["গুলাব জামুন","নরম গুলাব জামুন, খোয়া, সিরা ও এলাচ, ঈদ ও ভোজের সবচেয়ে প্রিয় মিষ্টি।","গোলাপের গন্ধ সহ সিরায় গুলাব জামুন"]},"gajarhalwa":{"ja":["ニンジンのハルワ","冬のニンジンのハルワ。赤いニンジン、牛乳、コヤ、ギー。家と同じ味。","コヤとアーモンドのニンジンのハルワ"],"de":["Gajar Ka Halwa","Winterlicher Gajar Ka Halwa, rote Karotten, Milch, Khoya und Ghee, genau wie zu Hause.","Gajar Ka Halwa mit Khoya und Mandeln"],"tr":["Gajar Ka Halwa","Kışlık gajar ka halwa, kırmızı havuç, süt, khoya ve ghee, tıpkı evdeki gibi.","Khoya ve bademli gajar ka halwa"],"bn":["গাজরের হালুয়া","শীতের গাজরের হালুয়া, লাল গাজর, দুধ, খোয়া ও ঘি, ঠিক বাড়ির মতো।","খোয়া ও বাদাম সহ গাজরের হালুয়া"]},"lassi":{"ja":["マンゴーラッシー","冷たいマンゴーラッシー。熟したマンゴー、ヨーグルト、カルダモン。夏にいちばん心地よいドリンク。","マンゴーとミントのマンゴーラッシーのグラス"],"de":["Mango-Lassi","Gekühlter Mango-Lassi, reife Mangos, Joghurt und Kardamom, das wohltuendste Getränk im Sommer.","Ein Glas Mango-Lassi mit Mango und Minze"],"tr":["Mango Lassi","Soğuk mango lassi, olgun mangolar, yoğurt ve kakule, yazın en rahatlatıcı içeceği.","Mango ve naneli bir bardak mango lassi"],"bn":["আমের লস্যি","ঠান্ডা আমের লস্যি, পাকা আম, দই ও এলাচ, গ্রীষ্মের সবচেয়ে আরামদায়ক পানীয়।","আম ও পুদিনা সহ এক গ্লাস আমের লস্যি"]},"pizza":{"ja":["マルゲリータピザ","イタリアから。トマト、フィオール・ディ・ラッテ・モッツァレラ、新鮮なバジルのクラシックなナポリピザ。","トマトソース、溶けたモッツァレラ、新鮮なバジルのマルゲリータピザ"],"de":["Margherita-Pizza","Aus Italien, eine klassische neapolitanische Pizza mit Tomate, Fior-di-Latte-Mozzarella und frischem Basilikum.","Eine Margherita-Pizza mit Tomatensoße, geschmolzenem Mozzarella und frischem Basilikum"],"tr":["Margherita Pizza","İtalyadan, domates, fior di latte mozzarella ve taze fesleğenli klasik Napoli pizzası.","Domates sosu, erimiş mozzarella ve taze fesleğenli bir margherita pizza"],"bn":["মার্গারিটা পিৎজা","ইতালি থেকে, টমেটো, ফিওর ডি লাটে মোজারেলা ও তাজা তুলসী সহ ক্লাসিক নেপোলিটান পিৎজা।","টমেটো সস, গলানো মোজারেলা ও তাজা তুলসী সহ একটি মার্গারিটা পিৎজা"]},"carbonara":{"ja":["スパゲッティ・カルボナーラ","イタリアから。卵とペコリーノで作るシルキーなスパゲッティ・カルボナーラ。クリームは一切なし。","パンチェッタ、卵のソース、すりおろしたペコリーノのスパゲッティ・カルボナーラ"],"de":["Spaghetti Carbonara","Aus Italien, seidige Spaghetti Carbonara mit Eiern und Pecorino, ganz ohne Sahne.","Spaghetti Carbonara mit Pancetta, Eiersoße und geriebenem Pecorino"],"tr":["Spaghetti Carbonara","İtalyadan, yumurta ve pecorino ile yapılan ipeksi spaghetti carbonara, hiç krema yok.","Pancetta, yumurta sosu ve rendelenmiş pecorinolu spaghetti carbonara"],"bn":["স্প্যাগেতি কার্বোনারা","ইতালি থেকে, ডিম ও পেকোরিনো দিয়ে তৈরি মসৃণ স্প্যাগেতি কার্বোনারা, একদম ক্রিম ছাড়া।","প্যানচেটা, ডিমের সস ও কুচানো পেকোরিনো সহ স্প্যাগেতি কার্বোনারা"]},"sushi":{"ja":["寿司","日本から。味付けご飯、海苔、少しのわさびのサーモンときゅうりの寿司ロール。","ご飯、海苔、ごまのサーモンときゅうりの寿司ロール"],"de":["Sushi","Aus Japan, Lachs- und Gurken-Sushirollen mit gewürztem Reis, Nori und ein wenig Wasabi.","Lachs- und Gurken-Sushirollen mit Reis, Nori und Sesam"],"tr":["Suşi","Japonyadan, baharatlı pilav, nori ve biraz wasabili somon ve salatalıklı suşi ruloları.","Pilav, nori ve susamlı somon ve salatalık suşi ruloları"],"bn":["সুশি","জাপান থেকে, মশলাদার ভাত, নোরি ও অল্প ওয়াসাবি সহ স্যামন ও শসার সুশি রোল।","ভাত, নোরি ও তিল সহ স্যামন ও শসার সুশি রোল"]},"ramen":{"ja":["ラーメン","日本から。濃厚なスープ、弾力のある麺、柔らかい卵、新鮮なトッピングのチキンラーメン。","麺、卵、チキン、ネギのチキンラーメンのボウル"],"de":["Ramen","Aus Japan, Hähnchen-Ramen mit reichhaltiger Brühe, fedrigen Nudeln, einem weichen Ei und frischen Toppings.","Eine Schale Hähnchen-Ramen mit Nudeln, Ei, Hähnchen und Frühlingszwiebeln"],"tr":["Ramen","Japonyadan, zengin et suyu, yaylanan erişte, yumuşak yumurta ve taze malzemeli tavuk ramen.","Erişte, yumurta, tavuk ve taze soğanlı bir kâse tavuk ramen"],"bn":["রামেন","জাপান থেকে, সমৃদ্ধ ঝোল, স্প্রিংগি নুডলস, নরম ডিম ও তাজা টপিং সহ চিকেন রামেন।","নুডলস, ডিম, মুরগি ও পেঁয়াজ পাতা সহ এক বাটি চিকেন রামেন"]},"tacos":{"ja":["タコス・アル・パストール","メキシコから。チリでマリネした豚肉、焼いたパイナップル、タマネギ、コリアンダーのタコス・アル・パストール。","マリネした豚肉、パイナップル、タマネギ、コリアンダーのタコス・アル・パストール"],"de":["Tacos al Pastor","Aus Mexiko, Tacos al Pastor mit in Chili mariniertem Schweinefleisch, gegrillter Ananas, Zwiebel und Koriander.","Tacos al Pastor mit mariniertem Schweinefleisch, Ananas, Zwiebel und Koriander"],"tr":["Tacos al Pastor","Meksikadan, biberle marine edilmiş domuz eti, ızgara ananas, soğan ve kişnişli tacos al pastor.","Marine edilmiş domuz eti, ananas, soğan ve kişnişli tacos al pastor"],"bn":["ট্যাকোস আল পাস্তর","মেক্সিকো থেকে, লঙ্কায় ম্যারিনেট করা শুয়োরের মাংস, ঝলসানো আনারস, পেঁয়াজ ও ধনেপাতা সহ ট্যাকোস আল পাস্তর।","ম্যারিনেট করা শুয়োরের মাংস, আনারস, পেঁয়াজ ও ধনেপাতা সহ ট্যাকোস আল পাস্তর"]},"pozole":{"ja":["ポソレ","メキシコから。ゆっくり煮込んだ豚肉、ホミニー、チリのスープの赤いポソレ。新鮮なトッピングで仕上げ。","豚肉、ホミニー、大根、キャベツ、ライムの赤いポソレのボウル"],"de":["Pozole","Aus Mexiko, rotes Pozole mit langsam gekochtem Schweinefleisch, Hominy und einer Chilibrühe, mit frischen Toppings verfeinert.","Eine Schale rotes Pozole mit Schweinefleisch, Hominy, Rettich, Kohl und Limette"],"tr":["Pozole","Meksikadan, yavaş pişmiş domuz eti, hominy ve biberli et suyuyla kırmızı pozole, taze malzemelerle tamamlanmış.","Domuz eti, hominy, turp, lahana ve limonlu bir kâse kırmızı pozole"],"bn":["পোজোলে","মেক্সিকো থেকে, ধীরে রান্না করা শুয়োরের মাংস, হোমিনি ও লঙ্কার ঝোল সহ লাল পোজোলে, তাজা টপিং দিয়ে শেষ করা।","শুয়োরের মাংস, হোমিনি, মূলা, বাঁধাকপি ও লেবু সহ এক বাটি লাল পোজোলে"]},"padthai":{"ja":["パッタイ","タイから。米麺、エビ、卵、甘酸っぱいソース、カリカリのピーナッツのパッタイ。","米麺、エビ、卵、ピーナッツ、ライムのパッタイ"],"de":["Pad Thai","Aus Thailand, Pad Thai mit Reisnudeln, Garnelen, Ei, einer süß-sauren Soße und knusprigen Erdnüssen.","Pad Thai mit Reisnudeln, Garnelen, Ei, Erdnüssen und Limette"],"tr":["Pad Thai","Taylanddan, pirinç eriştesi, karides, yumurta, tatlı ekşi sos ve çıtır fıstıklı pad thai.","Pirinç eriştesi, karides, yumurta, fıstık ve limonlu pad thai"],"bn":["প্যাড থাই","থাইল্যান্ড থেকে, চালের নুডলস, চিংড়ি, ডিম, মিষ্টি টক সস ও মচমচে বাদাম সহ প্যাড থাই।","চালের নুডলস, চিংড়ি, ডিম, বাদাম ও লেবু সহ প্যাড থাই"]},"pekingduck":{"ja":["北京ダック","中国から。パリパリのつやのある皮の北京ダック。薄いパンケーキにホイシンとネギを添えて。","お皿の上の、パリパリの黄金色の皮の丸ごとローストした北京ダック"],"de":["Pekingente","Aus China, Pekingente mit knuspriger, lackierter Haut, serviert in dünnen Pfannkuchen mit Hoisin und Frühlingszwiebeln.","Eine ganze gebratene Pekingente mit knuspriger goldener Haut auf einer Platte"],"tr":["Pekin Ördeği","Çinden, çıtır lakeli derili Pekin ördeği, hoisin ve taze soğanla ince kreplerde servis edilir.","Bir tabakta çıtır altın derili bütün kızarmış Pekin ördeği"],"bn":["পেকিং হাঁস","চীন থেকে, মচমচে চকচকে চামড়া সহ পেকিং হাঁস, হোইসিন ও পেঁয়াজ পাতা সহ পাতলা প্যানকেকে পরিবেশন করা হয়।","একটি প্লেটে মচমচে সোনালি চামড়া সহ পুরো ভাজা পেকিং হাঁস"]},"dimsum":{"ja":["点心","中国から。エビと豚肉の餃子の蒸し点心。チリとしょうゆのつけダレで熱々でどうぞ。","竹蒸し器の蒸し点心餃子"],"de":["Dim Sum","Aus China, gedämpftes Dim Sum mit Garnelen- und Schweinefleisch-Teigtaschen, heiß serviert mit Chili- und Sojadip.","Gedämpfte Dim-Sum-Teigtaschen in einem Bambusdämpfer"],"tr":["Dim Sum","Çinden, karides ve domuz etli mantılarla buharda pişmiş dim sum, acı biber ve soya sosuyla sıcak servis edilir.","Bambu buharlayıcıda buharda pişmiş dim sum mantıları"],"bn":["ডিম সাম","চীন থেকে, চিংড়ি ও শুয়োরের মাংসের ডাম্পলিং সহ ভাপে রান্না করা ডিম সাম, লঙ্কা ও সয়া ডিপিং সস সহ গরম পরিবেশন করা হয়।","বাঁশের স্টিমারে ভাপে রান্না করা ডিম সাম ডাম্পলিং"]},"coqauvin":{"ja":["コック・オー・ヴァン","フランスから。赤ワインでゆっくり煮込んだ鶏肉、マッシュルーム、ベーコン、パールオニオンのコック・オー・ヴァン。","赤ワインで煮込んだ鶏肉、マッシュルーム、パールオニオンのコック・オー・ヴァン"],"de":["Coq au Vin","Aus Frankreich, Coq au Vin, Hähnchen, langsam in Rotwein geschmort mit Pilzen, Speck und Perlzwiebeln.","Coq au Vin, Hähnchen in Rotwein geschmort mit Pilzen und Perlzwiebeln"],"tr":["Coq au Vin","Fransadan, coq au vin, kırmızı şarapta mantar, pastırma ve inci soğanla yavaşça haşlanmış tavuk.","Kırmızı şarapta mantar ve inci soğanla haşlanmış tavuk, coq au vin"],"bn":["কক ও ভাঁ","ফ্রান্স থেকে, কক ও ভাঁ, লাল ওয়াইনে মাশরুম, বেকন ও মুক্তো পেঁয়াজ সহ ধীরে সিদ্ধ করা মুরগি।","লাল ওয়াইনে মাশরুম ও মুক্তো পেঁয়াজ সহ সিদ্ধ করা মুরগি, কক ও ভাঁ"]},"bouillabaisse":{"ja":["ブイヤベース","フランスから。マルセイユのブイヤベース。サフランの魚のスープにミックスシーフード、トーストにルイユを添えて。","エビ、サフランのスープ、ハーブのブイヤベースの魚のスープの鍋"],"de":["Bouillabaisse","Aus Frankreich, Bouillabaisse aus Marseille, eine Safran-Fischsuppe mit gemischten Meeresfrüchten und Rouille auf Toast.","Ein Topf Bouillabaisse-Fischsuppe mit Garnelen, Safranbrühe und Kräutern"],"tr":["Bouillabaisse","Fransadan, Marsilya usulü bouillabaisse, karışık deniz ürünleri ve tost üzerine rouille ile safranlı balık çorbası.","Karides, safran suyu ve otlu bir tencere bouillabaisse balık çorbası"],"bn":["বুইয়াবেস","ফ্রান্স থেকে, মার্সেইয়ের বুইয়াবেস, মিশ্র সামুদ্রিক খাবার ও টোস্টে রুই সহ জাফরান মাছের স্যুপ।","চিংড়ি, জাফরান ঝোল ও ভেষজ সহ এক হাঁড়ি বুইয়াবেস মাছের স্যুপ"]},"paella":{"ja":["シーフードパエリア","スペインから。サフランの米、エビ、ムール貝、底のパリパリのソカラットのシーフードパエリア。","エビ、ムール貝、レモン、サフランの米の入った広いフライパンのシーフードパエリア"],"de":["Meeresfrüchte-Paella","Aus Spanien, Meeresfrüchte-Paella mit Safranreis, Garnelen und Miesmuscheln und dem knusprigen Socarrat am Boden.","Meeresfrüchte-Paella in einer weiten Pfanne mit Garnelen, Miesmuscheln, Zitrone und Safranreis"],"tr":["Deniz Ürünlü Paella","İspanyadan, safranlı pilav, karides ve midyeli deniz ürünlü paella ve dipte çıtır socarrat.","Karides, midye, limon ve safranlı pilavlı geniş tavada deniz ürünlü paella"],"bn":["সি-ফুড পায়েলা","স্পেন থেকে, জাফরান ভাত, চিংড়ি ও ঝিনুক সহ সি-ফুড পায়েলা, এবং নিচে মচমচে সোকারাট।","চিংড়ি, ঝিনুক, লেবু ও জাফরান ভাত সহ চওড়া প্যানে সি-ফুড পায়েলা"]},"beefpho":{"ja":["ビーフフォー","ベトナムから。澄んだスパイスのスープ、米麺、薄切りの牛肉、新鮮なハーブのビーフフォー。","米麺、スライスした牛肉、ハーブ、もやしのビーフフォーのボウル"],"de":["Rindfleisch-Pho","Aus Vietnam, Rindfleisch-Pho mit einer klaren, gewürzten Brühe, Reisnudeln, dünn geschnittenem Rindfleisch und frischen Kräutern.","Eine Schale Rindfleisch-Pho mit Reisnudeln, geschnittenem Rindfleisch, Kräutern und Sojasprossen"],"tr":["Dana Pho","Vietnamdan, berrak baharatlı et suyu, pirinç eriştesi, ince dilimlenmiş dana eti ve taze otlarla dana pho.","Pirinç eriştesi, dilimlenmiş dana eti, otlar ve soya filizli bir kâse dana pho"],"bn":["বিফ ফো","ভিয়েতনাম থেকে, পরিষ্কার মশলাদার ঝোল, চালের নুডলস, পাতলা কাটা গরুর মাংস ও তাজা ভেষজ সহ বিফ ফো।","চালের নুডলস, কাটা গরুর মাংস, ভেষজ ও বিন স্প্রাউট সহ এক বাটি বিফ ফো"]},"poutine":{"ja":["プーティン","カナダから。サクサクのフライドポテト、きしむチーズカード、熱い牛肉または野菜のグレービーのプーティン。","チーズカードと熱いブラウンソースをのせたフライドポテトのプーティン"],"de":["Poutine","Aus Kanada, Poutine mit knusprigen Pommes, quietschenden Käsebruch und heißer Rindfleisch- oder Gemüsesoße.","Poutine, Pommes mit Käsebruch und heißer brauner Soße"],"tr":["Poutine","Kanadadan, çıtır patates kızartması, gıcırdayan peynir lorları ve sıcak dana veya sebze soslu poutine.","Peynir lorları ve sıcak kahverengi soslu patates kızartması, poutine"],"bn":["পাউটিন","কানাডা থেকে, মচমচে ফ্রেঞ্চ ফ্রাই, কিচকিচে চিজ কার্ড ও গরম গরুর মাংস বা সবজির গ্রেভি সহ পাউটিন।","চিজ কার্ড ও গরম বাদামি গ্রেভি সহ ফ্রেঞ্চ ফ্রাই, পাউটিন"]},"bobotie":{"ja":["ボボティ","南アフリカから。スパイスのきいたひき肉、フルーツ、黄金色の卵のトッピングのボボティ。イエローライスと一緒に。","卵のトッピングとベイリーフの南アフリカの焼きひき肉料理、ボボティ"],"de":["Bobotie","Aus Südafrika, Bobotie mit gewürztem Hackfleisch, Obst und einer goldenen Eierkruste, serviert mit gelbem Reis.","Bobotie, ein gebackenes südafrikanisches Hackfleischgericht mit Eierkruste und Lorbeerblättern"],"tr":["Bobotie","Güney Afrikadan, baharatlı kıyma, meyve ve altın yumurta kaplamalı bobotie, sarı pilavla servis edilir.","Yumurta kaplamalı ve defne yapraklı, fırında Güney Afrika kıyma yemeği, bobotie"],"bn":["বোবোটি","দক্ষিণ আফ্রিকা থেকে, মশলাদার কিমা, ফল ও সোনালি ডিমের টপিং সহ বোবোটি, হলুদ ভাতের সঙ্গে পরিবেশন করা হয়।","ডিমের টপিং ও তেজপাতা সহ বেক করা দক্ষিণ আফ্রিকার কিমার পদ, বোবোটি"]},"moussaka":{"ja":["ムサカ","ギリシャから。ナス、スパイスのきいたひき肉、厚い黄金色のベシャメルの層のムサカ。","ナス、ひき肉、ベシャメルの層のギリシャ風ムサカの一切れ"],"de":["Moussaka","Aus Griechenland, Moussaka mit Schichten aus Aubergine, gewürztem Hackfleisch und einer dicken goldenen Béchamelkruste.","Eine Scheibe griechische Moussaka mit Schichten aus Aubergine, Hackfleisch und Béchamel"],"tr":["Musakka","Yunanistandan, patlıcan, baharatlı kıyma ve kalın altın beşamel kaplamalı katmanlarla musakka.","Patlıcan, kıyma ve beşamel katmanlı bir dilim Yunan musakkası"],"bn":["মুসাকা","গ্রিস থেকে, বেগুনের স্তর, মশলাদার কিমা ও মোটা সোনালি বেচামেলের উপরের স্তর সহ মুসাকা।","বেগুন, কিমা ও বেচামেলের স্তর সহ গ্রিক মুসাকার একটি টুকরো"]},"hummus":{"ja":["フムス","中東から。タヒニ、レモン、ニンニクのシルキーでなめらかなフムス。温かいピタと一緒に。","オリーブオイル、ひよこ豆、ハーブのなめらかなフムスのボウル"],"de":["Hummus","Aus dem Nahen Osten, seidig glatter Hummus mit Tahini, Zitrone und Knoblauch, serviert mit warmer Pitta.","Eine Schale glatter Hummus mit Olivenöl, Kichererbsen und Kräutern"],"tr":["Humus","Orta Doğudan, tahin, limon ve sarımsaklı ipeksi pürüzsüz humus, sıcak pide ile servis edilir.","Zeytinyağı, nohut ve otlarla pürüzsüz bir kâse humus"],"bn":["হামাস","মধ্যপ্রাচ্য থেকে, তাহিনি, লেবু ও রসুন সহ মসৃণ মখমলি হামাস, গরম পিটা সহ পরিবেশন করা হয়।","অলিভ অয়েল, ছোলা ও ভেষজ সহ এক বাটি মসৃণ হামাস"]},"falafel":{"ja":["ファラフェル","中東から。浸したひよこ豆、ハーブ、スパイスで作るカリカリのファラフェル。タヒニソースと一緒に。","サラダ、ピタ、タヒニソース、ハーブのファラフェルボール"],"de":["Falafel","Aus dem Nahen Osten, knusprige Falafel aus eingeweichten Kichererbsen, Kräutern und Gewürzen, mit Tahini-Soße.","Falafelbällchen mit Salat, Pitta, Tahini-Soße und Kräutern"],"tr":["Falafel","Orta Doğudan, ıslatılmış nohut, otlar ve baharatlarla yapılan çıtır falafel, tahin sosuyla.","Salata, pide, tahin sosu ve otlarla falafel topları"],"bn":["ফালাফেল","মধ্যপ্রাচ্য থেকে, ভেজানো ছোলা, ভেষজ ও মশলা দিয়ে তৈরি মচমচে ফালাফেল, তাহিনি সস সহ।","সালাদ, পিটা, তাহিনি সস ও ভেষজ সহ ফালাফেল বল"]},"feijoada":{"ja":["フェイジョアーダ","ブラジルから。黒豆とミックスポークのフェイジョアーダ。ご飯、コラードグリーン、オレンジと一緒に。","土鍋の豚肉入りブラジル風黒豆シチュー、フェイジョアーダ"],"de":["Feijoada","Aus Brasilien, Feijoada mit schwarzen Bohnen und gemischtem Schweinefleisch, serviert mit Reis, Grünkohl und Orange.","Feijoada, brasilianischer Eintopf aus schwarzen Bohnen mit Schweinefleisch in einem Tontopf"],"tr":["Feijoada","Brezilyadan, siyah fasulye ve karışık domuz etli feijoada, pilav, kara lahana ve portakalla servis edilir.","Kil çömlekte domuz etli Brezilya siyah fasulye güveci, feijoada"],"bn":["ফেইজোয়াডা","ব্রাজিল থেকে, কালো বিন ও মিশ্র শুয়োরের মাংস সহ ফেইজোয়াডা, ভাত, কলার্ড গ্রিনস ও কমলা সহ পরিবেশন করা হয়।","মাটির হাঁড়িতে শুয়োরের মাংস সহ ব্রাজিলিয়ান কালো বিনের স্টু, ফেইজোয়াডা"]},"meatpie":{"ja":["オージーミートパイ","オーストラリアから。濃厚な牛肉のフィリングをサクサクの黄金色のパイ生地で包んだクラシックなミートパイ。トマトソースと一緒に。","牛肉のフィリングが見えるように切った黄金色のパイ生地のオーストラリア風ミートパイ"],"de":["Aussie Meat Pie","Aus Australien, der klassische Meat Pie mit reichhaltiger Rindfleischfüllung in knusprigem goldenem Teig, serviert mit Tomatensoße.","Ein australischer Meat Pie mit goldenem Teig, aufgeschnitten, um die Rindfleischfüllung zu zeigen"],"tr":["Aussie Etli Turta","Avustralyadan, çıtır altın hamurda zengin dana etli dolgulu klasik etli turta, domates sosuyla servis edilir.","Dana etli dolguyu göstermek için kesilmiş, altın hamurlu bir Avustralya etli turtası"],"bn":["অসি মিট পাই","অস্ট্রেলিয়া থেকে, মচমচে সোনালি পেস্ট্রিতে সমৃদ্ধ গরুর মাংসের পুর সহ ক্লাসিক মিট পাই, টমেটো সস সহ পরিবেশন করা হয়।","গরুর মাংসের পুর দেখাতে কাটা সোনালি পেস্ট্রি সহ একটি অস্ট্রেলিয়ান মিট পাই"]},"haleem":{"ja":["パキスタン風ハリーム","ゆっくり煮込んだパキスタン風ハリーム。牛肉、小麦、レンズ豆をすりつぶして濃厚でシルキーな粥にし、揚げ玉ねぎとレモンとともに。","揚げ玉ねぎ、ショウガ、青唐辛子、コリアンダー、レモンをのせたパキスタン風ハリームのボウル"],"de":["Pakistanisches Haleem","Langsam gekochtes pakistanisches Haleem, Rindfleisch, Weizen und Linsen zu einem dicken, seidigen Brei gestampft, serviert mit Röstzwiebeln und Zitrone.","Eine Schale pakistanisches Haleem mit Röstzwiebeln, Ingwer, grünen Chilis, Koriander und Zitrone"],"tr":["Pakistan Usulü Haleem","Yavaş pişmiş Pakistan usulü haleem; dana eti, buğday ve mercimek kalın, ipeksi bir lapaya ezilir, kızarmış soğan ve limonla servis edilir.","Kızarmış soğan, zencefil, yeşil biber, kişniş ve limonlu bir kâse Pakistan usulü haleem"],"bn":["পাকিস্তানি হালিম","ধীরে রান্না করা পাকিস্তানি হালিম, গরুর মাংস, গম ও ডাল মথে ঘন, মসৃণ হালুয়া, ভাজা পেঁয়াজ ও লেবু দিয়ে পরিবেশন করা হয়।","ভাজা পেঁয়াজ, আদা, কাঁচা মরিচ, ধনেপাতা ও লেবু দেওয়া এক বাটি পাকিস্তানি হালিম"]}};
